/**
 * Sea distances and days at sea for benchmark energy routes, generated by
 * worker/scripts/gen_routes.py (searoute on the Eurostat maritime network, Natural Earth ports; ADR
 * 0013). Orders of magnitude for comparing routes, not navigation.
 */

import data from "./routes.json";

export interface RouteVariant {
  via: string;
  nm: number;
  days: number;
  passages: string[];
}

export interface Port {
  name: string;
  /** The terminal this port stands in for, when the terminal is not in Natural Earth. */
  standsFor: string | null;
}

export interface Route {
  id: string;
  label: string;
  cargo: "crude" | "lng";
  origin: Port;
  destination: Port;
  variants: RouteVariant[];
}

export const ROUTES = data.routes as Route[];
export const KNOTS = data.knots as Record<Route["cargo"], number>;

/** Extra days at sea of a variant over the route's shortest variant (0 for the shortest). */
export function extraDays(route: Route, variant: RouteVariant): number {
  const shortest = Math.min(...route.variants.map((v) => v.days));
  return Math.round((variant.days - shortest) * 10) / 10;
}
